import React, { useState, useRef } from 'react';
import './MicRecorder.css';

const MicRecorder = ({ onTranscript }) => {
  const [listening, setListening] = useState(false);
  const recognitionRef = useRef(null);
  const keepListeningRef = useRef(false); // 🔁 controls looped restart

  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;

  const startListening = () => {
    if (!SpeechRecognition) {
      alert("Browser doesn't support Speech Recognition API");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.interimResults = false;
    recognition.continuous = false; // ✅ set to false to capture complete utterance

    recognition.onstart = () => {
      console.log("🎤 Listening...");
      setListening(true);
    };

    recognition.onresult = (event) => {
      const transcript = event.results[0][0].transcript;
      console.log("✅ Transcript:", transcript);
      onTranscript(transcript);
    };

    recognition.onend = () => {
      console.log("⏹️ Recognition ended");

      if (keepListeningRef.current) {
        console.log("🔁 Restarting recognition...");
        recognition.start();
      } else {
        setListening(false);
      }
    };

    recognition.onerror = (e) => {
      console.error("❌ Recognition error:", e);
      if (keepListeningRef.current) {
        recognition.start(); // retry on error
      } else {
        setListening(false);
      }
    };

    recognitionRef.current = recognition;
    keepListeningRef.current = true;
    recognition.start();
  };

  const stopListening = () => {
    keepListeningRef.current = false;
    if (recognitionRef.current) {
      recognitionRef.current.stop();
      setListening(false);
      console.log("🛑 Listening manually stopped");
    }
  };

  return (
    <div className="mic-container">
      {!listening ? (
        <button className="mic-button" onClick={startListening}>
          🎤 Start Listening
        </button>
      ) : (
        <button className="stop-button" onClick={stopListening}>
          🛑 Stop Listening
        </button>
      )}
    </div>
  );
};

export default MicRecorder;
